                char leftChar = s[left];
                have[leftChar]--;
                if (need.count(leftChar) && have[leftChar] < need[leftChar]) formed--;
                left++;
            }
        }
        if (bestLength == INT_MAX) return "";
        return s.substr(bestStart, bestLength);
    }
